 sections:[
 {id:"who",h:"Per chi",html:`<p>Club, coach e giocatori che si allenano da soli più volte a settimana. Chi gioca una volta a settimana quasi mai ne ha bisogno.</p>`},
 {id:"need",h:"Cosa serve",html:`<p>Campo o spazio dedicato, presa o batterie e 10–15 minuti per montare. Conservala al riparo; non è un accessorio da borsa.</p>`},
 {id:"use",h:"Uso tipico",html:`<p>Diritto, volée, bandeja a cadenza fissa. Parti lento. Palline: <a href="/it/palline/">hub</a>. Racchetta: <a href="/it/migliori/racchette-padel-principianti/">principianti</a> se stai ancora imparando.</p>`},
 {id:"alt",h:"Alternative",html:`<p>Muro, cesto con partner, lezione. Spesso più economico. Vedi <a href="/it/accessori-padel/">accessori</a>.</p>`},
 ],
